  '[{\"id\":\"slide-1\",\"projectId\":\"prj_sda_bk_54\",\"judul\":\"Rehabilitasi Saluran Pembuang Stasiun - Tembiring - Tuntang Lama\",\"subKegiatan\":\"Normalisasi/Restorasi Sungai\",\"bidangId\":\"sda_bk\",\"kategori\":\"Pekerjaan Konstruksi (Fisik)\",\"paguAnggaran\":1950036600,\"nilaiKontrak\":1911946000,\"pelaksana\":\"CV. ANUGRAH MEKAR JAYA\",\"nomorKontrak\":\"000.3.3/008/SP/TENDER/SDABK/VIII/2026\",\"progresFisik\":30,\"progresKeuangan\":30,\"sp2d\":573583800,\"lokasi\":\"Kecamatan Demak (Pusat Kota)\",\"deskripsi\":\"Pekerjaan strategis normalisasi dan rehabilitasi saluran pembuang air pengendali banjir perkotaan kawasan Stasiun, Tembiring hingga Tuntang Lama.\",\"url\":\"https://images.unsplash.com/photo-1578328819058-b69f3a3b0f6b?w=1200&auto=format&fit=crop&q=80\"}]',
  '{\"landing_hero_tagline\":\"Transparansi Pembangunan Infrastruktur Daerah\",\"landing_hero_title\":\"Portal Pemantauan Progres Pekerjaan\",\"landing_hero_desc\":\"Sistem resmi keterbukaan informasi publik untuk memantau kemajuan fisik, lokasi koordinat, dan tahapan pekerjaan infrastruktur jalan, jembatan, gedung, irigasi, dan penataan ruang secara akuntabel.\",\"landing_hero_btn_explore\":\"Jelajahi Pekerjaan Sorotan\",\"landing_hero_btn_slideshow\":\"Lihat Slideshow Foto\",\"landing_bidang_badge\":\"BIDANG PELAYANAN INFRASTRUKTUR\",\"landing_bidang_title\":\"Pembangunan Berkelanjutan di 4 Bidang Teknis\",\"landing_bidang_desc\":\"Setiap bidang di Dinas Pekerjaan Umum dan Penataan Ruang bertanggung jawab dalam memastikan kualitas dan ketepatan waktu pekerjaan strategis daerah.\",\"landing_sorotan_badge\":\"SOROTAN PUBLIK DINPUTARU\",\"landing_sorotan_title\":\"Pekerjaan Unggulan & Progres Terkini\",\"landing_sorotan_desc\":\"Daftar pekerjaan yang dipublikasikan secara terbuka untuk pengawasan partisipatif masyarakat.\",\"landing_peta_badge\":\"GEOGRAFIS & PEMETAAN\",\"landing_peta_title\":\"Peta Titik Koordinat Pekerjaan\",\"landing_peta_desc\":\"Masyarakat dapat memverifikasi langsung lokasi fisik pekerjaan di lapangan melalui integrasi koordinat latitude dan longitude.\",\"landing_footer_desc\":\"Sistem Informasi Monitoring Pekerjaan Dinas Pekerjaan Umum dan Penataan Ruang. Menyajikan data progres fisik dan status pengadaan infrastruktur daerah secara terbuka dan bertanggung jawab.\",\"landing_footer_access_desc\":\"Panel khusus bagi ASN, Pejabat Pembuat Komitmen (PPK), PPTK, dan Tim Verifikator Keuangan DINPUTARU Kabupaten Demak. Gunakan tombol Login pada sudut kanan atas untuk masuk ke dashboard internal.\",\"internal_dashboard_title\":\"Dashboard Eksekutif Monitoring Pekerjaan\",\"internal_dashboard_desc\":\"Pemantauan indikator kinerja utama (IKU), deviasi fisik, serapan anggaran, dan distribusi paket pekerjaan dinas.\",\"internal_prakontrak_title\":\"Monitoring Pekerjaan Sebelum Kontrak (Pra-Kontrak)\",\"internal_prakontrak_desc\":\"Monitoring alur tahapan persiapan dan pemilihan penyedia jasa konstruksi dari SiRUP, HPS, hingga kontrak kerja resmi.\",\"internal_fisik_title\":\"Monitoring Progres Fisik Pekerjaan (0\% - 100\%)\",\"internal_fisik_desc\":\"Pemantauan berkala realisasi fisik lapangan, kurva S, deviasi rencana vs aktual, dan dokumentasi foto 0\%, 50\%, 100\%.\",\"internal_keuangan_title\":\"Monitoring Progres Keuangan & Pencairan SP2D\",\"internal_keuangan_desc\":\"Pengendalian pencairan dana uang muka, termin, PHO, serta tracking kelengkapan berkas SPJ keuangan dinas.\",\"internal_spj_title\":\"Administrasi Verifikasi Berkas SPJ & SPM Keuangan\",\"internal_spj_desc\":\"Alur validasi dan verifikasi kelengkapan berkas tagihan rekanan oleh tim verifikator sebelum penerbitan SPM/SP2D.\",\"internal_master_title\":\"Master Data Pekerjaan (Basis Data Induk)\",\"internal_master_desc\":\"Pusat registrasi dan manajemen data dasar seluruh paket pekerjaan dinas terintegrasi ke modul monitoring.\",\"internal_pendapatan_title\":\"Monitoring Target & Realisasi Pendapatan Retribusi Daerah\",\"internal_pendapatan_desc\":\"Pengendalian target tahun berjalan (6 Miliar) dan realisasi penerimaan retribusi Setor Tinja, PBG, SLF, Sewa Alat Berat, dan Sewa Cor Drill.\",\"internal_report_title\":\"Cetak & Rekapitulasi Laporan Kedinasan\",\"internal_report_desc\":\"Format laporan resmi kedinasan siap cetak/PDF dan ekspor spreadsheet untuk pelaporan berkala pimpinan.\",\"internal_sipd_title\":\"Ringkasan Nomenklatur SIPD\",\"internal_sipd_badge\":\"SIPD RI\",\"internal_sipd_desc\":\"Pohon Hierarki Kinerja: Program → Kegiatan → Sub Kegiatan → Daftar Paket Pekerjaan dinas terintegrasi nomenklatur SIPD RI.\",\"internal_sipd_box_title\":\"Diagram Kotak: Komparasi Realisasi & Sebaran Anggaran Program\",\"internal_sipd_box_desc\":\"Perbandingan langsung pagu, nilai kontrak, serapan SP2D, realisasi fisik, dan deviasi kinerja antar Program SIPD DINPUTARU.\",\"internal_sipd_analytics_title\":\"Visual Analytics: Realisasi & Sebaran Anggaran SIPD\",\"internal_sipd_analytics_desc\":\"Komparasi Progres Fisik vs Keuangan dan Distribusi Pagu per Program, Kegiatan, dan Sub Kegiatan.\"}',
  '{\"bina_marga\":\"Pembangunan jalan kabupaten, rekonstruksi ruas poros, pemeliharaan jembatan, dan konektivitas transportasi antar wilayah.\",\"cipta_karya\":\"Pembangunan gedung workshop & kantor pelayanan, sanitasi masyarakat, serta penyediaan sarana air minum pedesaan.\",\"sda_bk\":\"Normalisasi sungai, rehabilitasi jaringan irigasi bendung, pencegahan banjir, dan pembinaan tenaga konstruksi daerah.\",\"tata_ruang\":\"Perencanaan tata ruang wilayah (RTRW/RDTR), kesesuaian kegiatan pemanfaatan ruang, dan tertib administrasi pertanahan.\"}',
  '[{\"id\":\"gal-1\",\"judul\":\"Gedung Kantor DINPUTARU Kabupaten Demak\",\"kategori\":\"Gedung Kantor\",\"lokasi\":\"Jl. Kyai Jebat No. 35 Bintoro Kec. Demak\",\"tahun\":2024,\"deskripsi\":\"Gedung induk pelayanan administrasi teknis dan penataan ruang DINPUTARU Kab. Demak.\",\"url\":\"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&auto=format&fit=crop&q=80\"},{\"id\":\"gal-2\",\"judul\":\"Penataan Kawasan Alun-Alun Simpang Enam Demak\",\"kategori\":\"Cipta Karya\",\"lokasi\":\"Kecamatan Demak (Pusat Kota)\",\"tahun\":2024,\"deskripsi\":\"Revitalisasi ruang terbuka hijau publik, pedestrian ramah disabilitas, dan ikon Kota Wali.\",\"url\":\"https://images.unsplash.com/photo-1519999482648-25049ddd37b1?w=800&auto=format&fit=crop&q=80\"},{\"id\":\"gal-3\",\"judul\":\"Pembangunan Jembatan Kracaan Dempet - Kebonagung\",\"kategori\":\"Bina Marga\",\"lokasi\":\"Kecamatan Dempet & Kebonagung\",\"tahun\":2025,\"deskripsi\":\"Jembatan gelagar beton pratekan bentang 40 meter penghubung sentra pertanian antar kecamatan.\",\"url\":\"https://images.unsplash.com/photo-1545558014-8692077e9b5c?w=800&auto=format&fit=crop&q=80\"},{\"id\":\"gal-4\",\"judul\":\"Tanggul Pengendali Banjir Sungai Wulan Karanganyar\",\"kategori\":\"Sumber Daya Air\",\"lokasi\":\"Desa Ketanjung, Kec. Karanganyar\",\"tahun\":2024,\"deskripsi\":\"Perkuatan parapet beton dan tanggul tanah kritis pencegah luapan banjir Sungai Wulan.\",\"url\":\"https://images.unsplash.com/photo-1578328819058-b69f3a3b0f6b?w=800&auto=format&fit=crop&q=80\"},{\"id\":\"gal-5\",\"judul\":\"Peninggian Jalan Rob & Tanggul Sayung - Morosari\",\"kategori\":\"Bina Marga\",\"lokasi\":\"Kecamatan Sayung (Pesisir)\",\"tahun\":2025,\"deskripsi\":\"Rekonstruksi jalan beton bertulang rigid pavement tahan genangan air rob pantai utara.\",\"url\":\"https://images.unsplash.com/photo-1541888946425-d0fbb18f15f7?w=800&auto=format&fit=crop&q=80\"},{\"id\":\"gal-6\",\"judul\":\"Pembangunan Embung Konservasi Air Tawar Timbulsloko\",\"kategori\":\"Sumber Daya Air\",\"lokasi\":\"Desa Timbulsloko, Kec. Sayung\",\"tahun\":2025,\"deskripsi\":\"Penyediaan cadangan air baku masyarakat pesisir di masa kemarau berkapasitas 45.000 m³.\",\"url\":\"https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80\"},{\"id\":\"gal-7\",\"judul\":\"Pusat Distribusi Air Minum SPAM Regional Wedung\",\"kategori\":\"Cipta Karya\",\"lokasi\":\"Kecamatan Wedung\",\"tahun\":2024,\"deskripsi\":\"Reservoir distribusi air bersih berkapasitas 50 liter/detik untuk 4.200 sambungan rumah.\",\"url\":\"https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=800&auto=format&fit=crop&q=80\"},{\"id\":\"gal-8\",\"judul\":\"Pengembangan Kawasan Industri & Logistik Sayung (RDTR)\",\"kategori\":\"Tata Ruang\",\"lokasi\":\"Koridor Tol Semarang - Demak Kec. Sayung\",\"tahun\":2025,\"deskripsi\":\"Perencanaan tata ruang terintegrasi simpul transportasi logistik dan sabuk mitigasi pesisir.\",\"url\":\"https://images.unsplash.com/photo-1497366216548-37526070297c?w=800&auto=format&fit=crop&q=80\"}]'
);

